import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {resolve,join} from 'node:path';
import {validateEvidence} from './apps/desktop-app/scripts/run-evidence.mjs';
import {captureProvenance} from './apps/desktop-app/scripts/build-provenance.mjs';
const family=process.argv[1], root=process.cwd(), run='docs/runs/ui-state-families';
const hash=b=>createHash('sha256').update(b).digest('hex');
const old=await readFile(join(run,'pre-correction-runner.mjs'),'utf8');
const current=await readFile('apps/desktop-app/scripts/e2e-workbench-states.mjs','utf8');
assert.equal(current.slice(0,current.indexOf('  const familyTasks = {')),old.slice(0,old.indexOf('  const familyTasks = {')),'shared capture/bootstrap unchanged');
assert.equal(current.slice(current.indexOf('    extensions: async () => {')),old.slice(old.indexOf('    extensions: async () => {')),'all focused family bodies/report/teardown unchanged');
const destination=resolve(run,'evidence',family+'-r1','ui-states');
const manifest=JSON.parse(await readFile(join(destination,'manifest.json')));
assert.equal(manifest.status,'pass'); assert.equal(manifest.exitCode,0); assert.equal(manifest.provenanceVerifiedAfter,true);
assert.equal(hash(old),manifest.provenance.selectedScriptsAndFixtures.files.find(f=>f.path.endsWith('/e2e-workbench-states.mjs')).sha256);
const provenance=await captureProvenance(root,{script:'ui-states',family});
for(const key of ['schemaVersion','buildStampPath','buildStampSha256','buildStamp','currentBuildInputs','launchArtifacts']) assert.deepEqual(provenance[key],manifest.provenance[key],key);
const changed=new Set(['apps/desktop-app/scripts/run-evidence.mjs','apps/desktop-app/scripts/e2e-workbench-states.mjs']);
assert.deepEqual(provenance.selectedScriptsAndFixtures.files.filter(f=>!changed.has(f.path)),manifest.provenance.selectedScriptsAndFixtures.files.filter(f=>!changed.has(f.path)));
const inventoryBytes=await readFile(join(run,'capture-inventory.json'));
assert.equal(hash(inventoryBytes),'4ef59f41de8ac35cbf9546228846fa9628afec4ba8271927708cfb3daab97154');
const inventory=JSON.parse(inventoryBytes).filter(f=>f.family===family);
const evidence=await validateEvidence(destination,'ui-states',family);
assert.equal(evidence.length-1,inventory.length);
for(const item of inventory){const bytes=await readFile(item.path);assert.equal(bytes.length,item.bytes);assert.equal(hash(bytes),item.sha256);assert.ok(evidence.includes(item.path.slice(item.path.indexOf('/ui-states/')+'/ui-states/'.length)));}
console.log(JSON.stringify({family,originalStartedAt:manifest.startedAt,captures:inventory.length,currentParser:'pass',buildBytes:'unchanged',focusedBodies:'unchanged',runtimeReexecuted:false}));

